class Solution:
    def keepAtMostTwo(self, values: List[int]) -> List[int]:
        out, i = [], 0
        while i < len(values):
            j = i
            while j < len(values) and values[j] == values[i]:
                j += 1
            out += [values[i]] * min(2, j - i)
            i = j
        return out

