class Solution {
public:
    vector<int> keepAtMostTwo(vector<int>& values) {
        vector<int> out;
        size_t i = 0;
        while (i < values.size()) {
            size_t j = i;
            while (j < values.size() && values[j] == values[i]) j++;
            out.insert(out.end(), min<size_t>(2, j - i), values[i]);
            i = j;
        }
        return out;
    }
};

