int* keepAtMostTwo(int* values, int valuesSize, int* returnSize) {
    int* out = malloc(valuesSize * sizeof(int));
    int w = 0, i = 0;
    while (i < valuesSize) {
        int j = i;
        while (j < valuesSize && values[j] == values[i]) j++;
        for (int c = 0; c < 2 && c < j - i; c++) out[w++] = values[i];
        i = j;
    }
    *returnSize = w;
    return out;
}

