class Solution {
    public int[] keepAtMostTwo(int[] values) {
        int[] a = values.clone();
        int write = 0;
        for (int x : values)
            if (write < 2 || a[write - 2] != x) a[write++] = x;
        return Arrays.copyOf(a, write);
    }
}

